/bin/zsh -lc "cat > index.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>North Works · Equipment checkout</title>
  <link rel="stylesheet" href="styles.css">
  <script src="app.js" defer></script>
</head>
<body>
  <main>
    <p class="eyebrow">North Works / Member desk</p>
    <h1>Equipment checkout</h1>
    <p class="help">Choose the tool you need, and let us know when it will be back.</p>
    <section class="panel" aria-label="Checkout details">
      <form id="checkout-form" novalidate>
        <p class="help">Both fields are required. This is a local preview; no reservation will be sent.</p>
        <div class="field">
          <label for="equipment">Equipment (required)</label>
          <select id="equipment" name="equipment" aria-describedby="equipment-error" required>
            <option value="">Choose equipment</option>
            <option value="sander">Orbital sander</option>
            <option value="drill">Cordless drill</option>
            <option value="clamps">Clamp set</option>
          </select>
          <p id="equipment-error" class="error" hidden></p>
        </div>
        <div class="field">
          <label for="return-date">Return date (required)</label>
          <input id="return-date" type="date" name="returnDate" aria-describedby="return-date-hint return-date-error" required>
          <p id="return-date-hint" class="help">Choose today or a later date.</p>
          <p id="return-date-error" class="error" hidden></p>
        </div>
        <button type="submit">Confirm checkout</button>
        <p id="checkout-status" class="error" role="status" aria-live="polite" aria-atomic="true"></p>
      </form>
      <section id="confirmation" aria-labelledby="confirmation-heading" hidden>
        <h2 id="confirmation-heading" tabindex="-1">Checkout summary</h2>
        <p>Confirmed in this preview. No reservation has been sent.</p>
        <dl class="summary">
          <div><dt>Equipment</dt><dd id="summary-equipment"></dd></div>
          <div><dt>Return date</dt><dd><time id="summary-date"></time></dd></div>
        </dl>
        <button id="edit-checkout" type="button">Edit checkout</button>
      </section>
      <noscript><p class="error">Enable JavaScript to confirm your checkout in this local preview.</p></noscript>
    </section>
  </main>
</body>
</html>
EOF
cat > app.js <<'"'EOF'
'use strict';

const form = document.querySelector('#checkout-form');
const equipment = document.querySelector('#equipment');
const returnDate = document.querySelector('#return-date');
const status = document.querySelector('#checkout-status');
const confirmation = document.querySelector('#confirmation');

function localToday() {
  const now = new Date();
  return "'`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '"'0')}-"'${String(now.getDate()).padStart(2, '"'0')}"'`;
}

function setError(input, message) {
  const error = document.querySelector(`#${input.id}-error`);
  error.textContent = message;
  error.hidden = !message;
  if (message) {
    input.setAttribute('"'aria-invalid', 'true');
  } else {
    input.removeAttribute('aria-invalid');
  }
}

function validate(input) {
  let message = '';
  if (input === equipment) {
    if ("'!equipment.value || !equipment.selectedOptions.length) {
      message = '"'Choose a piece of equipment.';
    }
  } else {
    // Refresh at submission too, in case the page has stayed open overnight.
    returnDate.min = localToday();
    if (returnDate.validity.badInput) {
      message = 'Enter a complete, valid return date.';
    } else if ("'!returnDate.value) {
      message = '"'Choose a return date.';
    } else if ("'!returnDate.validity.valid) {
      message = '"'Choose today or a later valid date.';
    }
  }
  setError(input, message);
  return "'!message;
}

returnDate.min = localToday();

for (const input of [equipment, returnDate]) {
  input.addEventListener('"'input', () => {
    status.textContent = '';
    if (input.hasAttribute('aria-invalid')) validate(input);
  });
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const equipmentValid = validate(equipment);
  const dateValid = validate(returnDate);

  if ("'!equipmentValid || !dateValid) {
    status.textContent = '"'Please correct the marked fields before confirming.';
    (equipmentValid ? returnDate : equipment).focus();
    return;
  }

  document.querySelector('#summary-equipment').textContent = equipment.selectedOptions[0].textContent;
  const summaryDate = document.querySelector('#summary-date');
  // Format calendar dates in UTC to avoid shifting the selected day by time zone.
  summaryDate.textContent = new Intl.DateTimeFormat(undefined, {
    year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC'
  }).format(new Date("'`${returnDate.value}T00:00:00Z`));
  summaryDate.setAttribute('"'datetime', returnDate.value);
  status.textContent = '';
  form.hidden = true;
  confirmation.hidden = false;
  document.querySelector('#confirmation-heading').focus();
});

 document.querySelector('#edit-checkout').addEventListener('click', () => {
  confirmation.hidden = true;
  form.hidden = false;
  returnDate.min = localToday();
  equipment.focus();
});
EOF"

